    /// A validated bound adapter; a private handle is never a binder index.
    pub(crate) fn bound_id(&self, symbol: &SymbolRef) -> Result<Option<SymbolId>, SymbolAccessError> {
        self.view(symbol)?;
        Ok(match symbol.0 { Identity::Bound(_, id) => Some(id), Identity::Private(_, _) => None })
    }

    /// Member construction copies declaration metadata without a merge redirect.
    pub(crate) fn new_member_from(&mut self, source: &SymbolRef, check_flags: CheckFlags) -> Result<SymbolRef, SymbolAccessError> {
        let view = self.view(source)?;
        let flags = view.flags();
        let name = Cow::Owned(view.name().to_owned());
        let declarations = view.declarations().to_vec();
        let value_declaration = view.value_declaration();
        let parent = view.parent();
        Ok(self.add(PrivateSymbol {
            flags: flags | SymbolFlags::TRANSIENT, check_flags, name, declarations,
            value_declaration, parent, export_symbol:None, members:None, exports:None,
            origin:Some(source.clone()), declared_type:None,
        }))
    }

